    .wvalid({m_axi_gmem5_WVALID,m_axi_gmem4_WVALID,m_axi_gmem3_WVALID,m_axi_gmem2_WVALID,m_axi_gmem1_WVALID,m_axi_gmem0_WVALID}), .wready({m_axi_gmem5_WREADY,m_axi_gmem4_WREADY,m_axi_gmem3_WREADY,m_axi_gmem2_WREADY,m_axi_gmem1_WREADY,m_axi_gmem0_WREADY}),
